from fractions import Fraction
from sympy import sqrt

def show(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def paren(x):
    if x < 0:
        return f"({x})"
    return str(x)

def minor(A, i, j):
    return [A[k][:j] + A[k][j + 1:] for k in range(len(A)) if k != i]

def det(A):
    if len(A) == 1:
        return A[0][0]
    return sum((-1) ** j * A[0][j] * det(minor(A, 0, j)) for j in range(len(A)))

def length(data):
    v = data[0]
    total = sum(x * x for x in v)
    print(f"  |{show(v)}| = sqrt({' + '.join(str(x * x) for x in v)}) = {sqrt(total)}, about {float(sqrt(total)):.4f}")

def dot(data):
    u, v = data
    if len(u) != len(v):
        print(f"  undefined: lengths {len(u)} and {len(v)}")
        return
    products = [u[i] * v[i] for i in range(len(u))]
    print(f"  {show(u)} · {show(v)} = {' + '.join(paren(p) for p in products)} = {sum(products)}")

def cross(data):
    u, v = data
    w = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]]
    checks = [sum(w[i] * u[i] for i in range(3)), sum(w[i] * v[i] for i in range(3))]
    print(f"  {show(u)} × {show(v)} = {show(w)}, checks {checks[0]} and {checks[1]}")

def matvec(data):
    A, x = data[:-1], data[-1]
    if len(x) != len(A[0]):
        print(f"  undefined: {len(A[0])} columns need {len(A[0])} weights")
        return
    parts = [paren(x[j]) + show([row[j] for row in A]) for j in range(len(x))]
    b = [sum(row[j] * x[j] for j in range(len(x))) for row in A]
    print(f"  Ax = {' + '.join(parts)} = {show(b)}")

def inverse2(data):
    a, b = data[0]
    c, d = data[1]
    D = a * d - b * c
    print(f"  ad - bc = {paren(a)}·{paren(d)} - {paren(b)}·{paren(c)} = {D}")
    if D == 0:
        print("  singular: no inverse")
        return
    print(f"  inverse: rows {show([d / D, -b / D])} and {show([-c / D, a / D])}")

def determinant(data):
    pieces = []
    for j in range(len(data)):
        pieces.append(f"{paren((-1) ** j * data[0][j])}·{paren(det(minor(data, 0, j)))}")
    print(f"  along row 1, signs + - + ...: {' + '.join(pieces)} = {det(data)}")

methods = {"length": length, "dot": dot, "cross": cross, "matvec": matvec,
           "inverse2": inverse2, "det": determinant}
problems = [("dot", [[3, -2, 1], [4, 5, 2]]), ("cross", [[2, 1, 0], [1, 3, 4]]),
            ("length", [[2, -3, 6]]), ("matvec", [[1, 2, 0], [3, -1, 4], [2, 1, -1]]),
            ("inverse2", [[3, 5], [1, 2]]), ("det", [[2, 1, 3], [0, 4, 1], [1, 0, 2]]),
            ("dot", [[1, 2], [1, 2, 3]]), ("inverse2", [[2, 6], [1, 3]]), ("length", [[1, 1]])]
for i in range(len(problems)):
    kind, rows = problems[i]
    data = [[Fraction(t) for t in row] for row in rows]
    print(f"Problem {i + 1}: {kind}")
    methods[kind](data)

