from fractions import Fraction

def show(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def paren(x):
    if x < 0:
        return f"({x})"
    return str(x)

def dot(u, v):
    return sum(u[i] * v[i] for i in range(len(u)))

def work(data):
    F, d = data
    products = [paren(F[i] * d[i]) for i in range(len(F))]
    print(f"  W = F·d = {' + '.join(products)} = {dot(F, d)} joules")

def garden(data):
    P, Q, R = data
    a, b = Q[0] - P[0], Q[1] - P[1]
    c, d = R[0] - P[0], R[1] - P[1]
    print(f"  sides ({a}, {b}) and ({c}, {d}), so ad - bc = {a * d - b * c}")
    print(f"  area = |ad - bc|/2 = {abs(a * d - b * c) / 2} square meters")

def recipe(data):
    A, x = data[:-1], data[-1]
    parts = [f"{x[j]}{show([row[j] for row in A])}" for j in range(len(x))]
    print(f"  amounts times the columns: {' + '.join(parts)} = {show([dot(row, x) for row in A])}")

def moving(data):
    M, x, years = data[0:2], data[2], data[3][0]
    for year in range(int(years)):
        x = [dot(M[i], x) for i in range(2)]
        print(f"  after year {year + 1}: M times the last = {show(x)}")

def mix(data):
    a, b, e = data[0]
    c, d, f = data[1]
    D = a * d - b * c
    if D == 0:
        print("  ad - bc = 0: no inverse, so no single answer")
        return
    print(f"  ad - bc = {D}, so A^-1 = (1/{paren(D)}) times rows ({d}, {-b}) and ({-c}, {a})")
    x = f"({paren(d)}·{paren(e)} + {paren(-b)}·{paren(f)})/{paren(D)} = {(d * e - b * f) / D}"
    print(f"  x = {x}, y = ({paren(-c)}·{paren(e)} + {paren(a)}·{paren(f)})/{paren(D)} = {(a * f - c * e) / D}")

def resize(data):
    A, area = data[0:2], data[2][0]
    D = A[0][0] * A[1][1] - A[0][1] * A[1][0]
    print(f"  det A = {D}, so every area is multiplied by |det A| = {abs(D)}")
    print(f"  {area} square cm becomes {abs(D) * area} square cm")

methods = {"work": work, "garden": garden, "recipe": recipe, "moving": moving, "mix": mix, "resize": resize}
problems = [("work", [[24, 7], [25, 0]]), ("garden", [[0, 0], [10, 2], [3, 8]]),
            ("mix", [[1, 1, 9], [14, 6, 94]]), ("recipe", [[3, 2], [2, 3], [1, 2], [4, 3]]),
            ("moving", [["4/5", "1/10"], ["1/5", "9/10"], [500, 500], [2]]), ("resize", [[4, 1], [1, 2], [9]]),
            ("mix", [[3, 1, 11], [1, 2, 7]]), ("garden", [[0, 0], [1, 4], [5, 1]]), ("mix", [[2, 4, 10], [1, 2, 5]])]
for i in range(len(problems)):
    kind, rows = problems[i]
    data = [[Fraction(t) for t in row] for row in rows]
    print(f"Problem {i + 1}: {kind}")
    methods[kind](data)

